//! 🧪️ The original native wrapper publishes one independently admitted named root under its original ledger.
use semio_framework_test_fixtures::fixture_text;
use super::*;
use crate::{DslValue,Number,NativeDecodeControl,NamedPersistentRoot,native_decoding::{NativeDecodeConstructionRecipient,owned::{NativeReceivingOriginal,NativeFlatRecord,NativeRecordField}}};
#[derive(semio_framework_value_derive::RetireOwned)]#[value(crate="crate")]struct ReceivedRow{key:SealedShared<String>,payload:Number}
impl crate::NamedRecordKey for ReceivedRow{fn named_record_key(&self)->&str{self.key.as_str()}}
impl Clone for ReceivedRow{fn clone(&self)->Self{panic!("original named receiving cannot clone typed rows")}}
impl NativeFlatRecord<1,1> for ReceivedRow{
 const TEXT_FIELDS:[NativeRecordField;1]=[NativeRecordField{name:"key",ordinal:0}];const NUMBER_FIELDS:[NativeRecordField;1]=[NativeRecordField{name:"payload",ordinal:1}];
 fn validation_demand(_: [&str;1],_: [Number;1])->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Number>()+size_of::<usize>(),depth:1,..Default::default()}}
 fn validate_parts(_: [&str;1],numbers:[Number;1])->Result<(),ValueError>{if numbers[0].as_i64().is_some(){Ok(())}else{Err(invalid())}}
 fn from_parts([key]:[SealedShared<String>;1],[payload]:[Number;1])->Self{Self{key,payload}}
}
semio_framework_value_native_owned::native_flat_record_receive!(ReceivedRow,1,1);
struct ConstructionTurn{original:RetainedCloneGrant,granted:bool,accepted:bool}
impl NativeDecodeConstructionRecipient for ConstructionTurn{
 fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{assert!(!self.granted);assert!(retained_clone_grant_admits(self.original,d));self.granted=true;Ok(self.original)}
 fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{assert!(self.granted&&!self.accepted);assert_eq!(g,self.original);assert!(p.fits(g));self.accepted=true;Ok(())}
}
fn receive<R>(control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant,f:impl FnOnce(&mut NativeDecodeControl<'_>)->Result<R,ValueError>)->Result<R,ValueError>{let mut recipient=ConstructionTurn{original:g,granted:false,accepted:false};let result=control.with_construction_recipient(&mut recipient,f);if result.is_ok(){assert_eq!(recipient.granted,recipient.accepted);}result}
fn fund(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096,"original named root quote {} exceeds authored 4096-byte quantum",d.copy_bytes);RetainedCloneGrant{maximum_items:257,maximum_copy_bytes:4096,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn account(p:RetainedCloneProgress,g:RetainedCloneGrant,h:(usize,usize),total:&mut(usize,usize)){assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));total.0+=h.0;total.1+=h.1;}
fn close_value<T:RetireOwned>(value:T,total:&mut(usize,usize)){let(mut close,h)=heap(||ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap());total.0+=h.0;total.1+=h.1;while !close.terminal_is_empty(){let g=fund(close.next_demand(4096).unwrap());let(s,h)=heap(||close.step(g).unwrap());account(s.progress(),g,h,total);}assert_eq!(heap(||drop(close)).1,(0,0));}
fn run_received(keys:&[String],admitted:bool,cut:Option<usize>){
 type Owner=NativeReceivingOriginal<DslValue,NamedPersistentRoot<ReceivedRow>>;
 let(mut original,mut total)=heap(||Some(source(DslValue::Array(keys.iter().enumerate().map(|(rank,key)|DslValue::Object(vec![("key".into(),DslValue::String(key.clone())),("payload".into(),DslValue::Number(Number::Int(rank as i64)))])).collect()))));
 let pointer=std::ptr::from_ref(original.as_ref().unwrap().borrow().get());let expected=serde_json::Value::from(original.as_ref().unwrap().borrow().get());let(mut owner,p)=Owner::begin_shell(fund(Owner::shell_demand())).unwrap();assert!(p.fits(fund(Owner::shell_demand())));let g=fund(owner.original_capture_demand().unwrap());let(p,h)=heap(||owner.admit_original(&mut original,g).unwrap());account(p,g,h,&mut total);assert!(original.is_none());
 let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let d=owner.receiver_birth_demand().unwrap();let g=fund(d);control.charge(d.capacity_bytes).unwrap();let(p,h)=heap(||owner.begin_receiver(g).unwrap());account(p,g,h,&mut total);let mut prepared=h.0;assert_eq!(control.owned_bytes(),prepared);let mut turns=0;let mut refused=false;
 while !owner.output_ready()&&cut.is_none_or(|cut|turns<cut){let d=owner.demands(4096).unwrap();let g=fund(d);for denied in denies(d){let(s,h)=heap(||receive(&mut control,denied,|control|owner.advance(control,4096,denied)).unwrap());assert_eq!(h,(0,0));assert_eq!(s.progress(),Default::default());assert_eq!(owner.demands(4096).unwrap(),d);}let(result,h)=heap(||receive(&mut control,g,|control|owner.advance(control,4096,g)));let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());account(p,g,h,&mut total);prepared+=h.0;assert_eq!(control.owned_bytes(),prepared);assert_eq!(std::ptr::from_ref(owner.borrow_input().unwrap().get()),pointer);assert_eq!(serde_json::Value::from(owner.borrow_input().unwrap().get()),expected);turns+=1;assert!(turns<1000000);if let Err(e)=result{assert_eq!(e.kind,ValueRefusalKind::InvalidValue);refused=true;break;}}
 let mut output=None;if cut.is_none(){assert_eq!(owner.output_ready(),admitted);assert_eq!(refused,!admitted);if admitted{let g=fund(owner.take_demand().unwrap());let((root,p),h)=heap(||owner.take(g).unwrap().unwrap());account(p,g,h,&mut total);assert_eq!(root.len(),keys.len());let ranked=root.ranked().unwrap();for(rank,key)in keys.iter().enumerate(){let row=ranked.original.get().get(rank).unwrap();assert_eq!(row.key.as_str(),key);assert_eq!(row.payload.as_i64(),Some(rank as i64));}output=Some(root);}}
 owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demands(4096).unwrap();for denied in denies(d){let(s,h)=heap(||owner.close_step(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));}let g=fund(d);control.charge(d.capacity_bytes).unwrap();let(s,h)=heap(||owner.close_step(g).unwrap());account(s.progress(),g,h,&mut total);prepared+=h.0;assert_eq!(control.owned_bytes(),prepared);}assert_eq!(heap(||drop(owner)).1,(0,0));
 if let Some(root)=output{let d=root.project_index_demand().unwrap();let((mut alias,p),h)=heap(||root.project_index(fund(d)).unwrap().unwrap());account(p,fund(d),h,&mut total);let ranked=root.ranked().unwrap();let original_key=ranked.key;let d=RetainedOwnedProjection::<PersistentList<ReceivedRow>>::constructor_demand();for denied in denies(d){let(result,h)=heap(||root.project_rows(denied));assert!(result.is_err());assert_eq!(h,(0,0));}let((mut reader,p),h)=heap(||root.project_rows(fund(d)).unwrap());assert!(reader.matches_source(ranked.original));account(p,fund(d),h,&mut total);close_value(root,&mut total);let live=PersistentRankedKeys{original:reader.borrow().unwrap(),key:original_key};for(rank,key)in keys.iter().enumerate(){assert_eq!(lookup(&live,&alias,key).0,Some(rank));}let(b,r)=close_index(&mut alias);total.0+=b;total.1+=r;while !reader.terminal_is_empty(){let g=fund(reader.close_demand(4096).unwrap());let(s,h)=heap(||reader.close_step(g).unwrap());account(s.progress(),g,h,&mut total);}assert_eq!(heap(||drop(reader)).1,(0,0));}
 assert_eq!(total.0,total.1,"original input, typed pages, admission directory and independent source must settle on the same physical ledger");println!("[DEBUG] original named receiving rows={} cut={cut:?} admitted={admitted} turns={turns} decoderLedger={prepared} physicalBirth={} physicalRelease={} quantum=4096 originalInputPointer=true terminalDrop=0",keys.len(),total.0,total.1);
}
#[test]fn original_named_receiving_publishes_independent_roots_and_closes_every_paid_cut(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../🔑️named/📇️index/🌳️root/🛬️receive/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap(){let keys=row["keys"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<Vec<_>>();for cut in f["cuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize)).chain(std::iter::once(None)){run_received(&keys,row["admitted"].as_bool().unwrap(),cut);}}}
#[test]fn original_named_receiving_checks_full_utf8_under_original_decoder_quantum(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../🔑️named/📇️index/🌳️root/🛬️receive/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let prefix=f["prefix"].as_str().unwrap().repeat(f["repeat"].as_u64().unwrap()as usize);assert_eq!(prefix.len(),65538);for cut in f["cuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize)).chain(std::iter::once(None)){run_received(&[prefix.clone(),format!("{prefix}x")],true,cut);}}
